  CHECK ((json_type(rubric) = 'object')),
  UNIQUE (slug, version),
  CHECK ((version > 0))
);
CREATE TABLE geo_local_area_vibe_scores (
  local_area_id TEXT NOT NULL,
  vibe_id TEXT NOT NULL,
  score INTEGER NOT NULL CHECK (score IS NULL OR typeof(score) = 'integer'),
  confidence REAL NOT NULL CHECK (confidence IS NULL OR typeof(confidence) IN ('integer','real')),
  evidence TEXT NOT NULL CHECK (evidence IS NULL OR json_valid(evidence)),
  source_type TEXT NOT NULL,
  scored_at TEXT NOT NULL CHECK (scored_at IS NULL OR julianday(scored_at) IS NOT NULL),
  expires_at TEXT CHECK (expires_at IS NULL OR julianday(expires_at) IS NOT NULL),
  CHECK (((confidence >= (0)) AND (confidence <= (1)))),
  CHECK ((json_type(evidence) IN ('object', 'array'))),
  FOREIGN KEY (local_area_id) REFERENCES geo_local_areas(id) ON DELETE CASCADE,
  PRIMARY KEY (local_area_id, vibe_id),
  CHECK (((score >= 0) AND (score <= 100))),
  CHECK ((source_type IN ('curated', 'spot_aggregate', 'social_aggregate', 'survey'))),
  FOREIGN KEY (vibe_id) REFERENCES geo_vibe_taxonomy(id) ON DELETE RESTRICT
);
CREATE TABLE social_spot_submission_aliases (
  alias_url TEXT NOT NULL,
  submission_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  PRIMARY KEY (alias_url),
  FOREIGN KEY (submission_id) REFERENCES social_spot_submissions(id) ON DELETE CASCADE
);
CREATE INDEX idx_social_spot_submission_aliases_submission ON social_spot_submission_aliases (submission_id);
CREATE TABLE social_spot_submission_candidates (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  submission_id TEXT NOT NULL,
  candidate_key TEXT NOT NULL,
  ordinal INTEGER NOT NULL CHECK (ordinal IS NULL OR typeof(ordinal) = 'integer'),
  spot_id TEXT,
  status TEXT NOT NULL,
  research TEXT NOT NULL DEFAULT '{}' CHECK (research IS NULL OR json_valid(research)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  UNIQUE (submission_id, candidate_key),
  CHECK ((ordinal >= 0)),
  PRIMARY KEY (id),
  FOREIGN KEY (spot_id) REFERENCES spots(id) ON DELETE SET NULL,
  CHECK ((status IN ('spot_created', 'spot_reused', 'needs_review', 'research_pending'))),
  FOREIGN KEY (submission_id) REFERENCES social_spot_submissions(id) ON DELETE CASCADE
);
CREATE INDEX idx_social_spot_submission_candidates_order ON social_spot_submission_candidates (submission_id, ordinal);
CREATE INDEX idx_social_spot_submission_candidates_spot ON social_spot_submission_candidates (spot_id) WHERE (spot_id IS NOT NULL);
CREATE TABLE social_spot_submission_media (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  submission_id TEXT NOT NULL,
  ordinal INTEGER NOT NULL CHECK (ordinal IS NULL OR typeof(ordinal) = 'integer'),
  media_key TEXT NOT NULL,
  media_type TEXT NOT NULL,
  source_url TEXT NOT NULL,
  fingerprint TEXT NOT NULL,
  revision INTEGER NOT NULL CHECK (revision IS NULL OR typeof(revision) = 'integer'),
  is_current INTEGER NOT NULL DEFAULT 1 CHECK (is_current IS NULL OR is_current IN (0,1)),
  payload TEXT NOT NULL DEFAULT '{}' CHECK (payload IS NULL OR json_valid(payload)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  CHECK (((fingerprint = trim(fingerprint)) AND ((length(fingerprint) >= 1) AND (length(fingerprint) <= 512)))),
  UNIQUE (submission_id, media_key),
  CHECK (((media_key = trim(media_key)) AND ((length(media_key) >= 1) AND (length(media_key) <= 512)))),
  CHECK ((media_type IN ('image', 'video', 'unknown'))),
  CHECK (((ordinal >= 0) AND (ordinal <= 34))),
  CHECK ((json_type(payload) = 'object')),
  PRIMARY KEY (id),
  CHECK ((revision > 0)),
  CHECK (((source_url = trim(source_url)) AND ((length(source_url) >= 1) AND (length(source_url) <= 8192)))),
  FOREIGN KEY (submission_id) REFERENCES social_spot_submissions(id) ON DELETE CASCADE,
  UNIQUE (submission_id, id)
);
CREATE INDEX idx_social_spot_submission_media_current_revision ON social_spot_submission_media (submission_id, revision, ordinal) WHERE is_current;
CREATE UNIQUE INDEX social_spot_submission_media_current_ordinal_unique ON social_spot_submission_media (submission_id, ordinal) WHERE is_current;
CREATE TABLE social_spot_submission_media_jobs (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  submission_id TEXT NOT NULL,
  media_id TEXT NOT NULL,
  ordinal INTEGER NOT NULL CHECK (ordinal IS NULL OR typeof(ordinal) = 'integer'),
  media_key TEXT NOT NULL,
  media_type TEXT NOT NULL,
  source_url TEXT NOT NULL,
  payload TEXT NOT NULL DEFAULT '{}' CHECK (payload IS NULL OR json_valid(payload)),
  revision INTEGER NOT NULL CHECK (revision IS NULL OR typeof(revision) = 'integer'),
  fingerprint TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'queued',
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count IS NULL OR typeof(attempt_count) = 'integer'),
  max_attempts INTEGER NOT NULL DEFAULT 5 CHECK (max_attempts IS NULL OR typeof(max_attempts) = 'integer'),
  available_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (available_at IS NULL OR julianday(available_at) IS NOT NULL),
  claim_token TEXT,
  claimed_by TEXT,
  claimed_at TEXT CHECK (claimed_at IS NULL OR julianday(claimed_at) IS NOT NULL),
  lease_expires_at TEXT CHECK (lease_expires_at IS NULL OR julianday(lease_expires_at) IS NOT NULL),
  succeeded_at TEXT CHECK (succeeded_at IS NULL OR julianday(succeeded_at) IS NOT NULL),
  dead_lettered_at TEXT CHECK (dead_lettered_at IS NULL OR julianday(dead_lettered_at) IS NOT NULL),
  cancelled_at TEXT CHECK (cancelled_at IS NULL OR julianday(cancelled_at) IS NOT NULL),
  last_error TEXT,
  result TEXT CHECK (result IS NULL OR json_valid(result)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  CHECK ((attempt_count <= max_attempts)),
  CHECK ((attempt_count >= 0)),
  CHECK (((claimed_by IS NULL) OR ((length(claimed_by) >= 1) AND (length(claimed_by) <= 200)))),
  CHECK (((fingerprint = trim(fingerprint)) AND ((length(fingerprint) >= 1) AND (length(fingerprint) <= 512)))),
  CHECK (((last_error IS NULL) OR (length(last_error) <= 8000))),
  CHECK ((((state = 'leased') AND (claim_token IS NOT NULL) AND (claimed_by IS NOT NULL) AND (claimed_at IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((state <> 'leased') AND (claim_token IS NULL) AND (lease_expires_at IS NULL)))),
  CHECK (((max_attempts >= 1) AND (max_attempts <= 10))),
  FOREIGN KEY (submission_id, media_id) REFERENCES social_spot_submission_media(submission_id, id) ON DELETE CASCADE,
  CHECK (((media_key = trim(media_key)) AND ((length(media_key) >= 1) AND (length(media_key) <= 512)))),
  UNIQUE (media_id, revision),
  CHECK ((media_type IN ('image', 'video', 'unknown'))),
  CHECK (((ordinal >= 0) AND (ordinal <= 34))),
  UNIQUE (submission_id, revision, ordinal),
  CHECK ((json_type(payload) = 'object')),
  PRIMARY KEY (id),
  CHECK ((revision > 0)),
  CHECK (((source_url = trim(source_url)) AND ((length(source_url) >= 1) AND (length(source_url) <= 8192)))),
  CHECK ((state IN ('queued', 'leased', 'retry_wait', 'succeeded', 'dead_letter', 'cancelled'))),
  CHECK ((((state <> 'succeeded') OR (succeeded_at IS NOT NULL)) AND ((state <> 'dead_letter') OR (dead_lettered_at IS NOT NULL)) AND ((state <> 'cancelled') OR (cancelled_at IS NOT NULL))))
);
CREATE INDEX idx_social_spot_submission_media_jobs_expired_lease ON social_spot_submission_media_jobs (submission_id, revision, lease_expires_at, created_at) WHERE (state = 'leased');
CREATE INDEX idx_social_spot_submission_media_jobs_media_fk ON social_spot_submission_media_jobs (submission_id, media_id);
CREATE INDEX idx_social_spot_submission_media_jobs_ready ON social_spot_submission_media_jobs (submission_id, revision, available_at, created_at) WHERE (state IN ('queued', 'retry_wait'));
CREATE INDEX idx_social_spot_submission_media_jobs_revision ON social_spot_submission_media_jobs (submission_id, revision, ordinal);
CREATE UNIQUE INDEX social_spot_submission_media_jobs_claim_token_unique ON social_spot_submission_media_jobs (claim_token) WHERE (claim_token IS NOT NULL);
CREATE TABLE transfer_edges (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  slug TEXT NOT NULL,
  from_destination_id TEXT NOT NULL,
  to_destination_id TEXT NOT NULL,
  mode TEXT NOT NULL,
  duration_min_minutes INTEGER NOT NULL CHECK (duration_min_minutes IS NULL OR typeof(duration_min_minutes) = 'integer'),
  duration_max_minutes INTEGER NOT NULL CHECK (duration_max_minutes IS NULL OR typeof(duration_max_minutes) = 'integer'),
  departure_buffer_minutes INTEGER NOT NULL CHECK (departure_buffer_minutes IS NULL OR typeof(departure_buffer_minutes) = 'integer'),
  arrival_buffer_minutes INTEGER NOT NULL CHECK (arrival_buffer_minutes IS NULL OR typeof(arrival_buffer_minutes) = 'integer'),
  hotel_change_minutes INTEGER NOT NULL DEFAULT 45 CHECK (hotel_change_minutes IS NULL OR typeof(hotel_change_minutes) = 'integer'),
  cost_band TEXT NOT NULL,
  booking_hint TEXT NOT NULL DEFAULT '{}' CHECK (booking_hint IS NULL OR json_valid(booking_hint)),
  schedule_notes TEXT NOT NULL DEFAULT '{}' CHECK (schedule_notes IS NULL OR json_valid(schedule_notes)),
  source_type TEXT NOT NULL,
  source_meta TEXT NOT NULL CHECK (source_meta IS NULL OR json_valid(source_meta)),
  confidence REAL NOT NULL CHECK (confidence IS NULL OR typeof(confidence) IN ('integer','real')),
  review_status TEXT NOT NULL,
  reviewed_at TEXT CHECK (reviewed_at IS NULL OR julianday(reviewed_at) IS NOT NULL),
  valid_from TEXT CHECK (valid_from IS NULL OR (length(valid_from) = 10 AND date(valid_from) = valid_from)),
  valid_until TEXT CHECK (valid_until IS NULL OR (length(valid_until) = 10 AND date(valid_until) = valid_until)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  CHECK ((arrival_buffer_minutes >= 0)),
  CHECK ((json_type(booking_hint) = 'object')),
  CHECK ((duration_max_minutes >= duration_min_minutes)),
  CHECK ((from_destination_id <> to_destination_id)),
  CHECK (((confidence >= (0)) AND (confidence <= (1)))),
  CHECK ((cost_band IN ('budget', 'moderate', 'premium'))),
  CHECK ((departure_buffer_minutes >= 0)),
  CHECK ((duration_min_minutes > 0)),
  FOREIGN KEY (from_destination_id) REFERENCES geo_destinations(id) ON DELETE RESTRICT,
  UNIQUE (from_destination_id, to_destination_id, mode, source_type),
  CHECK ((hotel_change_minutes >= 0)),
  CHECK ((mode IN ('flight', 'train', 'bus', 'ferry', 'car', 'taxi', 'rideshare', 'transit'))),
  PRIMARY KEY (id),
  CHECK ((review_status IN ('draft', 'machine_checked', 'human_verified', 'needs_review'))),
  CHECK ((json_type(schedule_notes) = 'object')),
  CHECK ((length(slug) > 0 AND slug NOT GLOB '*[^a-z0-9-]*' AND slug NOT GLOB '-*' AND slug NOT GLOB '*-' AND slug NOT GLOB '*--*')),
  UNIQUE (slug),
  CHECK ((json_type(source_meta) = 'object')),
  CHECK ((source_type IN ('curated', 'google_routes', 'gtfs', 'operator'))),
  FOREIGN KEY (to_destination_id) REFERENCES geo_destinations(id) ON DELETE RESTRICT
);
CREATE INDEX transfer_edges_route_idx ON transfer_edges (from_destination_id, to_destination_id, review_status);
CREATE TABLE user_challenges (
  user_id TEXT NOT NULL,
  challenge_id TEXT NOT NULL,
  progress TEXT DEFAULT '{}' CHECK (progress IS NULL OR json_valid(progress)),
  completed INTEGER DEFAULT 0 CHECK (completed IS NULL OR completed IN (0,1)),
  completed_at TEXT CHECK (completed_at IS NULL OR julianday(completed_at) IS NOT NULL),
  FOREIGN KEY (challenge_id) REFERENCES challenges(id),
  PRIMARY KEY (user_id, challenge_id),
  FOREIGN KEY (user_id) REFERENCES profiles(id)
);
CREATE TABLE user_progress (
  user_id TEXT NOT NULL,
  discoveries INTEGER DEFAULT 0 CHECK (discoveries IS NULL OR typeof(discoveries) = 'integer'),
  spots_visited INTEGER DEFAULT 0 CHECK (spots_visited IS NULL OR typeof(spots_visited) = 'integer'),
  tourist_traps_avoided INTEGER DEFAULT 0 CHECK (tourist_traps_avoided IS NULL OR typeof(tourist_traps_avoided) = 'integer'),
  current_streak INTEGER DEFAULT 0 CHECK (current_streak IS NULL OR typeof(current_streak) = 'integer'),
  achievements TEXT DEFAULT '[]' CHECK (achievements IS NULL OR json_valid(achievements)),
  unlocked_cities TEXT DEFAULT '[]' CHECK (unlocked_cities IS NULL OR (json_valid(unlocked_cities) AND json_type(unlocked_cities) = 'array')),
  updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  PRIMARY KEY (user_id),
  FOREIGN KEY (user_id) REFERENCES profiles(id)
);
CREATE TABLE weekly_city_spot_rankings (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  week_start TEXT NOT NULL CHECK (week_start IS NULL OR (length(week_start) = 10 AND date(week_start) = week_start)),
  city_slug TEXT NOT NULL,
  spot_id TEXT NOT NULL,
  rank INTEGER NOT NULL CHECK (rank IS NULL OR typeof(rank) = 'integer'),
  score REAL NOT NULL CHECK (score IS NULL OR typeof(score) IN ('integer','real')),
  post_count INTEGER NOT NULL DEFAULT 0 CHECK (post_count IS NULL OR typeof(post_count) = 'integer'),
  platform_count INTEGER NOT NULL DEFAULT 0 CHECK (platform_count IS NULL OR typeof(platform_count) = 'integer'),
  signal_summary TEXT NOT NULL DEFAULT '{}' CHECK (signal_summary IS NULL OR json_valid(signal_summary)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  PRIMARY KEY (id),
  CHECK (((platform_count >= 0) AND (platform_count <= 3))),
  CHECK ((post_count >= 0)),
  CHECK (((rank >= 1) AND (rank <= 5))),
  CHECK (((score >= (0)) AND (score <= (100)))),
  FOREIGN KEY (spot_id) REFERENCES spots(id) ON DELETE CASCADE,
  UNIQUE (week_start, city_slug, rank),
  UNIQUE (week_start, city_slug, spot_id)
);
CREATE INDEX weekly_city_spot_rankings_lookup_idx ON weekly_city_spot_rankings (city_slug, week_start DESC, rank);
CREATE TABLE weekly_social_content (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  week_start TEXT NOT NULL CHECK (week_start IS NULL OR (length(week_start) = 10 AND date(week_start) = week_start)),
  city_slug TEXT NOT NULL,
  platform TEXT NOT NULL,
  external_id TEXT NOT NULL,
  canonical_url TEXT NOT NULL,
  content_text TEXT NOT NULL DEFAULT '',
  published_at TEXT CHECK (published_at IS NULL OR julianday(published_at) IS NOT NULL),
  view_count INTEGER NOT NULL DEFAULT 0 CHECK (view_count IS NULL OR typeof(view_count) = 'integer'),
  like_count INTEGER NOT NULL DEFAULT 0 CHECK (like_count IS NULL OR typeof(like_count) = 'integer'),
  comment_count INTEGER NOT NULL DEFAULT 0 CHECK (comment_count IS NULL OR typeof(comment_count) = 'integer'),
  share_count INTEGER NOT NULL DEFAULT 0 CHECK (share_count IS NULL OR typeof(share_count) = 'integer'),
  save_count INTEGER NOT NULL DEFAULT 0 CHECK (save_count IS NULL OR typeof(save_count) = 'integer'),
  observed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (observed_at IS NULL OR julianday(observed_at) IS NOT NULL),
  expires_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now','+56 days')) CHECK (expires_at IS NULL OR julianday(expires_at) IS NOT NULL),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  place_hint TEXT,
  CHECK ((comment_count >= 0)),
  CHECK ((length(content_text) <= 4000)),
  CHECK ((like_count >= 0)),
  PRIMARY KEY (id),
  CHECK ((length(place_hint) <= 160)),
  CHECK ((platform IN ('instagram', 'tiktok', 'youtube'))),
  CHECK ((save_count >= 0)),
  CHECK ((share_count >= 0)),
  CHECK ((view_count >= 0)),
  UNIQUE (week_start, platform, external_id, city_slug)
);
CREATE INDEX weekly_social_content_city_week_idx ON weekly_social_content (city_slug, week_start DESC);
CREATE INDEX weekly_social_content_expiry_idx ON weekly_social_content (expires_at);
CREATE TABLE weekly_social_spot_leads (
  id TEXT NOT NULL DEFAULT (lower(hex(randomblob(4))||'-'||hex(randomblob(2))||'-4'||substr(hex(randomblob(2)),2)||'-'||substr('89ab',1+(abs(random())%4),1)||substr(hex(randomblob(2)),2)||'-'||hex(randomblob(6)))),
  week_start TEXT NOT NULL CHECK (week_start IS NULL OR (length(week_start) = 10 AND date(week_start) = week_start)),
  city_slug TEXT NOT NULL,
  platform TEXT NOT NULL,
  external_id TEXT NOT NULL,
  place_hint TEXT NOT NULL,
  normalized_hint TEXT NOT NULL,
  canonical_url TEXT NOT NULL,
  engagement_score INTEGER NOT NULL DEFAULT 0 CHECK (engagement_score IS NULL OR typeof(engagement_score) = 'integer'),
  status TEXT NOT NULL DEFAULT 'pending',
  discovery_run_id TEXT,
  searched_at TEXT CHECK (searched_at IS NULL OR julianday(searched_at) IS NOT NULL),
  expires_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now','+56 days')) CHECK (expires_at IS NULL OR julianday(expires_at) IS NOT NULL),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (created_at IS NULL OR julianday(created_at) IS NOT NULL),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) CHECK (updated_at IS NULL OR julianday(updated_at) IS NOT NULL),
  FOREIGN KEY (discovery_run_id) REFERENCES apify_spot_discovery_runs(id) ON DELETE SET NULL,
  CHECK ((engagement_score >= 0)),
  CHECK (((length(normalized_hint) >= 3) AND (length(normalized_hint) <= 160))),
