  CHECK ((platform IN ('instagram', 'tiktok', 'youtube'))),
  CHECK ((status IN ('pending', 'searching', 'searched', 'ignored'))),
  UNIQUE (week_start, city_slug, normalized_hint),
  UNIQUE (week_start, city_slug, platform, external_id)
);
CREATE INDEX weekly_social_spot_leads_expiry_idx ON weekly_social_spot_leads (expires_at);
CREATE INDEX weekly_social_spot_leads_queue_idx ON weekly_social_spot_leads (status, engagement_score DESC, created_at);
CREATE INDEX weekly_social_spot_leads_run_idx ON weekly_social_spot_leads (discovery_run_id) WHERE (discovery_run_id IS NOT NULL);
CREATE TABLE weekly_social_trend_city_builds (
  week_start TEXT NOT NULL CHECK (week_start IS NULL OR (length(week_start) = 10 AND date(week_start) = week_start)),
  city_slug TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'running',
  attempt_count INTEGER NOT NULL DEFAULT 1 CHECK (attempt_count IS NULL OR typeof(attempt_count) = 'integer'),
  error_message TEXT,
  lease_expires_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now','+10 minutes')) CHECK (lease_expires_at IS NULL OR julianday(lease_expires_at) IS NOT NULL),
  completed_at TEXT CHECK (completed_at IS NULL OR julianday(completed_at) IS NOT NULL),
